// curatedTaskSpec is deliberately written per topic. The old seed generated
// one sentence for every topic; that made an IKR page look populated while
// giving the student no mathematical object to solve.
type curatedTaskSpec struct {
	IKR       string
	IKRAnswer string
	TKR       string
	TKRAnswer string
}

func taskSpec(ikr, ikrAnswer, tkr, tkrAnswer string) curatedTaskSpec {
	return curatedTaskSpec{IKR: ikr, IKRAnswer: ikrAnswer, TKR: tkr, TKRAnswer: tkrAnswer}
}

